'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
let lang='en',data=null,bench='foldbench_abag',quality='acceptable',scale='ranked_high',budget=1;
const translated=$$('[data-zh]'); translated.forEach(e=>e.dataset.en=e.innerHTML);
const tr=(en,zh)=>lang==='zh'?zh:en;
function language(next){lang=next;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.classList.toggle('zh',lang==='zh');translated.forEach(e=>e.innerHTML=e.dataset[lang]);$('#language').textContent=lang==='zh'?'EN':'中文';$('#language').setAttribute('aria-label',tr('Switch to Chinese','切换到英文'));try{localStorage.setItem('cerebio-language',lang)}catch{}if(data){renderBenchmark();renderScaling();}renderCase(currentCase);}
$('#language').addEventListener('click',()=>language(lang==='en'?'zh':'en'));
$('#menu').addEventListener('click',()=>{const open=$('.header').classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));});
$$('.header nav a').forEach(a=>a.addEventListener('click',()=>{$('.header').classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}));
$$('.loop-step').forEach(b=>b.addEventListener('click',()=>{$$('.loop-step').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-expanded',String(active));x.querySelector('.step-icon').textContent=active?'−':'+';});}));
function setupTabs(selector,onSelect){const tabs=$$(selector+' [role=tab]');tabs.forEach((b,i)=>{b.tabIndex=b.getAttribute('aria-selected')==='true'?0:-1;b.addEventListener('click',()=>{tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});onSelect(b)});b.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight')j=(i+1)%tabs.length;if(e.key==='ArrowLeft')j=(i-1+tabs.length)%tabs.length;if(e.key==='Home')j=0;if(e.key==='End')j=tabs.length-1;if(j!==undefined){e.preventDefault();tabs[j].focus();tabs[j].click()}});});}
const panels={
 foldbench_abag:{en:'101 complexes · 154 interfaces<br>Interface-weighted · 5 seeds × 5 candidates',zh:'101 个复合物 · 154 个界面<br>界面等权 · 5 seeds × 5 个候选',ci:'−3.21, 16.88'},
 cofold_arena:{en:'376 targets<br>Target-weighted · seed 42 × 5 candidates',zh:'376 个靶标<br>靶标等权 · seed 42 × 5 个候选',ci:'6.64, 16.22'},
 af3_ab:{en:'64 complexes · 145 interfaces<br>59 clusters · equal cluster weights<br>5 seeds × 5 candidates',zh:'64 个复合物 · 145 个界面<br>59 个 clusters · cluster 等权<br>5 seeds × 5 个候选',ci:'9.00, 25.35'},
 pxmeter_ab:{en:'481 complexes · 996 interfaces<br>348 clusters · equal cluster weights<br>5 seeds × 5 candidates',zh:'481 个复合物 · 996 个界面<br>348 个 clusters · cluster 等权<br>5 seeds × 5 个候选',ci:'5.68, 14.90'}
};
const modelOrder=['Mol-1-RSI','CereFold-pro','Protenix-v2-RSI','Mol-1','Protenix-v2','ESMFold2','OpenDDE-G +T','OpenDDE-G -T','OpenDDE-AbAg +T','OpenDDE-AbAg -T','AlphaFold3','Boltz-1'];
setupTabs('.benchmark-tabs',b=>{bench=b.dataset.bench;if(data)renderBenchmark()});
$('#quality').addEventListener('change',e=>{quality=e.target.value;if(data)renderBenchmark()});
function renderBenchmark(){
 const rows=data.benchmarks.filter(r=>r.benchmark===bench && r[quality] !== null).sort((a,b)=>modelOrder.indexOf(a.model)-modelOrder.indexOf(b.model));
 const chart=$('#benchmark-chart'); chart.replaceChildren();
 rows.forEach(r=>{const row=document.createElement('div');row.className='bar-row'+(r.model==='Protenix-v2-RSI'?' is-rsi':r.model==='CereFold-pro'?' is-pro':r.model==='Mol-1-RSI'?' is-mol':'');const label=document.createElement('span');label.className='bar-label';label.textContent=r.model+(r.external?' *':'');const track=document.createElement('span');track.className='bar-track';const fill=document.createElement('span');fill.className='bar-fill';fill.style.width=r[quality]+'%';track.append(fill);const value=document.createElement('span');value.className='bar-value';value.textContent=r[quality].toFixed(2);row.append(label,track,value);row.title=r.model+': '+r[quality].toFixed(2)+'%';chart.append(row);});
 chart.setAttribute('aria-label',rows.map(r=>r.model+' '+r[quality].toFixed(2)+'%').join('; '));
 const baseline=rows.find(r=>r.model==='Protenix-v2')[quality],rsi=rows.find(r=>r.model==='Protenix-v2-RSI')[quality];
 $('#benchmark-delta').innerHTML='+'+(rsi-baseline).toFixed(2)+'<span>pp</span>';
 $('#benchmark-change').textContent=baseline.toFixed(2)+'% → '+rsi.toFixed(2)+'%';
 if(bench==='foldbench_abag'&&quality!=='acceptable')$('#ci-note').dataset.missing='Mol-1-RSI tier data omitted';
 const cutoff={acceptable:'0.23',medium:'0.49',high:'0.80'}[quality];
 $('#panel-details').innerHTML=panels[bench][lang]+'<br>DockQ '+rows[0].comparison.replace('>=','≥')+' '+cutoff;
 $('#ci-note').textContent=quality==='acceptable'?tr('95% paired-bootstrap interval for the gain: ['+panels[bench].ci+'] pp. 4,000 draws. '+(bench==='foldbench_abag'?'This interval includes zero.':''),'增益的 95% 配对 bootstrap 区间：['+panels[bench].ci+'] 个百分点。4,000 次重采样。'+(bench==='foldbench_abag'?'此区间包含零。':'')):tr('Point estimates. See the report for paired-bootstrap intervals and quality-tier definitions.','这里展示点估计。配对 bootstrap 区间及质量分级定义见报告。');
}
setupTabs('.dark-tabs',b=>{scale=b.dataset.scale;if(data)renderScaling()});
$('#budget').addEventListener('input',e=>{budget=Math.max(1,Math.min(1000,Math.round(10**(Number(e.target.value)*3/1000))));if(data)renderScaling()});
function svgEl(tag,attrs,content){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs||{}))e.setAttribute(k,v);if(content!==undefined)e.textContent=content;return e;}
function renderScaling(){
 const svg=$('#scaling-chart'),series=data.scaling[scale];svg.replaceChildren();
 const mobile=innerWidth<760,W=mobile?Math.max(280,innerWidth-40):1000,H=mobile?300:360,L=mobile?38:52,R=20,T=25,B=48,ymax=scale==='ranked_high'?60:scale==='oracle_high'?80:100;
 svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
 const x=k=>L+Math.log10(k)/3*(W-L-R),y=v=>H-B-v/ymax*(H-T-B);
 const title=svgEl('title',{},tr('Success across sampling budgets','不同采样预算下的成功率'));svg.append(title);
 const desc=svgEl('desc',{},tr('Two curves with minimum–maximum shading across ten random seed orderings. Use the seed budget slider to read exact values.','两条曲线及十次随机 seed 排列的最小–最大阴影范围。通过滑块查看精确数据。'));svg.append(desc);
 for(let v=0;v<=ymax;v+=20){svg.append(svgEl('line',{x1:L,x2:W-R,y1:y(v),y2:y(v),stroke:'#627257','stroke-opacity':v===0?.6:.23}));svg.append(svgEl('text',{x:L-14,y:y(v)+4,fill:'#8c9c7e','font-size':'11','text-anchor':'end'},v+'%'));}
 (mobile?[1,10,100,1000]:[1,5,20,100,500,1000]).forEach(k=>{svg.append(svgEl('text',{x:x(k),y:H-B+23,fill:'#8c9c7e','font-size':'11','text-anchor':'middle'},k.toLocaleString('en')))});
 svg.append(svgEl('text',{x:L,y:12,fill:'#a7b59a','font-size':'10','letter-spacing':'1'},tr('SUCCESS (%)','成功率 (%)')));
 svg.append(svgEl('text',{x:W-R,y:H-3,fill:'#8c9c7e','font-size':'10','text-anchor':'end'},tr('SEEDS · LOG SCALE','SEEDS · 对数坐标')));
 ['baseline','rsi'].forEach(model=>{const s=series[model],color=model==='rsi'?'#edb28a':'#a5b395';const upper=s.map(r=>`${x(r[0]).toFixed(2)},${y(r[3]).toFixed(2)}`),lower=[...s].reverse().map(r=>`${x(r[0]).toFixed(2)},${y(r[2]).toFixed(2)}`);svg.append(svgEl('path',{d:'M'+upper.join('L')+'L'+lower.join('L')+'Z',fill:color,'fill-opacity':'.09'}));svg.append(svgEl('path',{d:'M'+s.map(r=>`${x(r[0]).toFixed(2)},${y(r[1]).toFixed(2)}`).join('L'),fill:'none',stroke:color,'stroke-width':'2.1','stroke-linejoin':'round'}));});
 svg.append(svgEl('line',{x1:x(budget),x2:x(budget),y1:T,y2:H-B,stroke:'#ccd4bd','stroke-opacity':'.5','stroke-dasharray':'3 5'}));
 ['baseline','rsi'].forEach(model=>{const r=series[model][budget-1],color=model==='rsi'?'#edb28a':'#a5b395';svg.append(svgEl('circle',{cx:x(budget),cy:y(r[1]),r:5,fill:color,stroke:'#20261f','stroke-width':2}));$('#'+(model==='rsi'?'rsi':'baseline')+'-value').textContent=r[1].toFixed(2)+'%';});
 $('#budget-label').textContent=budget.toLocaleString('en');$('#budget').setAttribute('aria-valuetext',tr(budget+' seeds; RSI '+$('#rsi-value').textContent+'; baseline '+$('#baseline-value').textContent,budget+' 个 seeds；RSI '+$('#rsi-value').textContent+'；基线 '+$('#baseline-value').textContent));
}
